int fib4(int n) {
  List<int> results = [0, 0, 2, 0];
  if (n < 4) {
    return results[n];
  }

  for (int i = 4; i <= n; i++) {
    results.add(results[results.length - 1] + 
                results[results.length - 2] + 
                results[results.length - 3] + 
                results[results.length - 4]);
    results.removeAt(0);
  }

  return results[results.length - 1];
}

