bool correctBracketing(String brackets) {
  int depth = 0;
  for (int i = 0; i < brackets.length; i++) {
    String b = brackets[i];
    if (b == "<") {
      depth += 1;
    } else {
      depth -= 1;
    }
    if (depth < 0) {
      return false;
    }
  }
  return depth == 0;
}

