int vowelsCount(String s) {
  if (s.isEmpty) {
    return 0;
  }

  const vowels = "aeiouAEIOU";
  int nVowels = 0;

  for (int i = 0; i < s.length; i++) {
    if (vowels.contains(s[i])) {
      nVowels++;
    }
  }

  if (s[s.length - 1] == 'y' || s[s.length - 1] == 'Y') {
    nVowels++;
  }

  return nVowels;
}

