@pragma('vm:entry-point')
String circularShift(int x, int shift) {
  String s = x.toString();
  if (shift > s.length) {
    return s.split('').reversed.join('');
  } else {
    return s.substring(s.length - shift) + s.substring(0, s.length - shift);
  }
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(circularShift(12, 1)); // "21"
  print(circularShift(12, 2)); // "12"
  print(circularShift(12, 3)); // "21" (shift > digits, so reversed)
  print(circularShift(123, 1)); // "312"
  print(circularShift(123, 2)); // "231"
  print(circularShift(123, 5)); // "321" (shift > digits, so reversed)
}

