int hexKey(String num) {
  const primes = ['2', '3', '5', '7', 'B', 'D'];
  int total = 0;
  for (int i = 0; i < num.length; i++) {
    if (primes.contains(num[i])) {
      total += 1;
    }
  }
  return total;
}

