Map<String, int> histogram(String test) {
  Map<String, int> dict1 = {};
  List<String> list1 = test.split(" ");
  int t = 0;

  for (String i in list1) {
    if (list1.where((element) => element == i).length > t && i != '') {
      t = list1.where((element) => element == i).length;
    }
  }

  if (t > 0) {
    for (String i in list1) {
      if (list1.where((element) => element == i).length == t) {
        dict1[i] = t;
      }
    }
  }

  return dict1;
}

