@pragma('vm:entry-point')
int sumOddInEvenPosition(List<int> lst) {
  int sum = 0;
  for (int idx = 0; idx < lst.length; idx++) {
    if (idx % 2 == 0 && lst[idx] % 2 == 1) {
      sum += lst[idx];
    }
  }
  return sum;
}

@pragma('vm:entry-point')
int solution(List<int> lst) {
  return sumOddInEvenPosition(lst);
}

@pragma('vm:entry-point')
void main() {
  print(solution([5, 8, 7, 1])); // 12
  print(solution([3, 3, 3, 3, 3])); // 9
  print(solution([30, 13, 24, 321])); // 0
}

