@pragma('vm:entry-point')
List<int> getOddCollatz(int n) {
  List<int> oddCollatz = [];

  if (n % 2 != 0) {
    oddCollatz.add(n);
  }

  while (n > 1) {
    if (n % 2 == 0) {
      n = n ~/ 2;
    } else {
      n = n * 3 + 1;
    }

    if (n % 2 == 1) {
      oddCollatz.add(n);
    }
  }

  oddCollatz.sort();
  return oddCollatz;
}

