bool isSorted(List<int> lst) {
  if (lst.isEmpty) {
    return true;
  }

  Map<int, int> countDigit = {};
  for (var i in lst) {
    countDigit[i] = 0;
  }

  for (var i in lst) {
    countDigit[i] = countDigit[i]! + 1;
  }

  for (var i in lst) {
    if (countDigit[i]! > 2) {
      return false;
    }
  }

  for (int i = 1; i < lst.length; i++) {
    if (lst[i - 1] > lst[i]) {
      return false;
    }
  }

  return true;
}

