int? prodSigns(List<int> arr) {
  if (arr.isEmpty) return null;

  int prod = arr.contains(0) 
      ? 0 
      : (arr.where((x) => x < 0).length % 2 == 0 ? 1 : -1);

  return prod * arr.map((i) => i.abs()).reduce((a, b) => a + b);
}

