List<num> tri(int n) {
  if (n == 0) {
    return [1];
  }
  List<num> myTri = [1, 3];
  for (int i = 2; i <= n; i++) {
    if (i % 2 == 0) {
      myTri.add(i / 2 + 1);
    } else {
      myTri.add(myTri[i - 1] + myTri[i - 2] + (i + 3) / 2);
    }
  }
  return myTri;
}

