@pragma('vm:entry-point')
int digits(int n) {
  int product = 1;
  int oddCount = 0;
  for (var digit in n.toString().split('')) {
    int intDigit = int.parse(digit);
    if (intDigit % 2 == 1) {
      product = product * intDigit;
      oddCount++;
    }
  }
  if (oddCount == 0) {
    return 0;
  } else {
    return product;
  }
}

@pragma('vm:entry-point')
void main() {
  print(digits(1));    // 1
  print(digits(4));    // 0
  print(digits(235));  // 15
  print(digits(13579)); // 945
  print(digits(2468));  // 0
  print(digits(123));   // 3
}

