  // Test cases
  print(checkIfLastCharIsALetter("apple pie")); // false
  print(checkIfLastCharIsALetter("apple pi e")); // true
  print(checkIfLastCharIsALetter("apple pi e ")); // false
  print(checkIfLastCharIsALetter("")); // false
  print(checkIfLastCharIsALetter("a")); // true
  print(checkIfLastCharIsALetter("ab")); // false
  print(checkIfLastCharIsALetter("hello world z")); // true
  print(checkIfLastCharIsALetter("test123")); // false
}

