String wordsInSentence(String sentence) {
  List<String> newLst = [];
  for (String word in sentence.split(' ')) {
    int flg = 0;
    if (word.length == 1) {
      flg = 1;
    }
    for (int i = 2; i < word.length; i++) {
      if (word.length % i == 0) {
        flg = 1;
      }
    }
    if (flg == 0 || word.length == 2) {
      newLst.add(word);
    }
  }
  return newLst.join(' ');
}

